def seed_products(app):
    with app.app_context():
        for product_data in PRODUCTS:
            existing = StoneProduct.query.filter_by(avito_id=product_data["avito_id"]).first()
            if existing:
                continue
            product = StoneProduct(
                avito_id=product_data["avito_id"],
                title=product_data["title"],
                description=product_data["description"],
                price=product_data["price"],
                price_string=product_data["price_string"],
                images=json.dumps(product_data["images"], ensure_ascii=False),
                size=product_data["size"],
                season=product_data["season"],
                art=product_data["art"],
                condition=product_data["condition"],
                avito_url=product_data["avito_url"],
                is_active=True,
            )
            db.session.add(product)
        db.session.commit()
        print(f"Seeded {StoneProduct.query.count()} StoneProduct records.")

if __name__ == "__main__":
    import sys
    sys.path.insert(0, "..")
    from app import app
    seed_products(app)
